// Checkout conversion fix: ensure paidEvents increment on successful payment
const { logEvent } = require('./logger');
const { incrementMetric } = require('./metrics');

module.exports = function checkoutConversionFix(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function (body) {
    if (res.statusCode === 200 && body && body.success) {
      // Increment paidEvents on successful checkout
      incrementMetric('paidEvents', 1);
      logEvent('checkout_success', { orderId: body.orderId });
    }
    return originalJson(body);
  };
  next();
};
